theme.customCss:
/* Notion for Movix: custom CSS for a Motix theme. Use it with notion.motix.json (colours included), or paste it
   into Advanced > Custom CSS on a light theme. Rules start from #root and use !important to win over Movix. */

/* Notion's type: the system UI stack, regular tracking, no shouting. */
#root, #root button, #root input, #root select, #root textarea { font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI Variable Display", "Segoe UI", Helvetica, "Apple Color Emoji", Arial, sans-serif !important; letter-spacing: normal !important; }

/* No animated grid or halo behind the page: Notion pages are plain paper. */
#root canvas.absolute.inset-0.z-0.pointer-events-none, #root .square-bg-halo { display: none !important; }

/* Top bar: white, 45px, a hairline under it, like Notion's breadcrumb bar. */
#root header > [class~="absolute"][class~="inset-0"][class~="pointer-events-none"][class~="bg-gradient-to-b"][class~="z-0"] { background: #ffffff !important; border-bottom: 1px solid rgba(55, 53, 47, .09) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
#root header [class~="h-16"] { height: 45px !important; gap: 4px !important; }
#root header a[class~="text-2xl"] { font-size: 14px !important; transform: none !important; }
#root header a[class~="text-2xl"] > span { display: inline-block; color: #37352f !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: lowercase; }
#root header a[class~="text-2xl"] > span::first-letter { text-transform: uppercase; }
#root header a[class~="text-2xl"]::before { content: "🍿"; display: inline-grid; place-items: center; width: 22px; height: 22px; margin-right: 8px; border-radius: 4px; background: #f1f1ef; font-size: 13px; }
#root header nav a, #root header nav button { padding: 2px 8px !important; border-radius: 4px !important; color: #37352f !important; font-size: 14px !important; font-weight: 400 !important; }
#root header nav a:hover, #root header nav button:hover { background: rgba(55, 53, 47, .08) !important; }
#root header nav svg { display: none !important; }
#root header form input { height: 28px !important; border: 0 !important; border-radius: 6px !important; background: #f7f7f5 !important; font-size: 14px !important; }

/* Page body: a centred column with breathing room, starting right under the bar. */
#root .content-wrapper { max-width: 1240px; margin-inline: auto !important; }
#root .content-wrapper > [class~="pt-16"] { padding-top: 45px !important; }

/* The home slider becomes a Notion cover: edge to edge, square, short. */
#root .embla { padding: 0 !important; }
#root .embla > [class~="relative"][class~="overflow-hidden"] { height: 300px !important; min-height: 0 !important; max-height: 34vh !important; border-radius: 0 !important; box-shadow: none !important; }
#root .embla__slide > [class~="absolute"][class~="inset-0"][class~="flex"] { align-items: flex-end !important; padding-bottom: 28px !important; }
/* Framing: the cover is short, so the image sits higher to keep faces in view. */
#root .embla__slide > img { object-position: center 18% !important; }
#root .embla__slide > [class~="absolute"][class~="inset-0"][class~="pointer-events-none"] { opacity: .6; }
/* The slide's content is compacted to fit the cover: tags, title logo, button. The description goes. */
#root .embla__slide p { display: none !important; }
#root .embla__slide [class~="pb-20"] { padding-bottom: 22px !important; }
#root .embla__slide [class~="space-y-3"] > * + * { margin-top: 10px !important; }
#root .embla__slide [class~="h-[64px]"] { height: auto !important; }
#root .embla__slide img[class~="object-contain"] { max-height: 64px !important; }
#root .embla__slide h1, #root .embla__slide h2 { font-size: 28px !important; }
/* Tags in Notion's own tag colours: type in blue, year in gray, rating in yellow. */
#root .embla__slide span[class~="rounded-full"][class~="border"] { padding: 1px 7px !important; border: 0 !important; border-radius: 3px !important; background: #e3e2e0 !important; color: #32302c !important; font-size: 13px !important; font-weight: 500 !important; letter-spacing: 0 !important; text-transform: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
#root .embla__slide span[class~="rounded-full"][class~="bg-white/15"] { background: #d3e5ef !important; color: #183347 !important; }
#root .embla__slide span[class~="rounded-full"][class~="bg-yellow-500/25"] { background: #fdecc8 !important; color: #402c1b !important; }
#root .embla__slide span[class~="rounded-full"] svg { color: currentColor !important; opacity: .7; }
/* "More info" as a plain Notion button. */
#root .embla__slide a[class~="bg-white/15"] { min-height: 32px !important; padding: 0 12px !important; border: 1px solid rgba(55, 53, 47, .16) !important; border-radius: 4px !important; background: #ffffff !important; color: #37352f !important; font-size: 14px !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
#root .embla__slide a[class~="bg-white/15"] svg { color: #37352f !important; }

/* ...then the page icon overlapping the cover and the page title, like any Notion page. */
#root .embla::after { content: "🍿"; position: absolute; left: clamp(24px, 8vw, 96px); bottom: -44px; z-index: 40; font-size: 72px; line-height: 1; }
#root .content-wrapper > [class~="pt-16"]::after { content: "Movix"; display: block; padding: 60px clamp(24px, 8vw, 96px) 4px; color: #37352f; font-size: 40px; font-weight: 700; line-height: 1.2; }

/* Buttons: small, flat, 4px corners. */
#root .embla__slide a, #root .embla__slide button { border-radius: 4px !important; box-shadow: none !important; font-weight: 500 !important; }

/* Section titles as Notion headings, with the drag handle that appears on hover. */
#root .section-title { position: relative; color: #37352f !important; text-shadow: none !important; -webkit-text-fill-color: #37352f !important; font-size: 22px !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: none !important; }
#root .section-title::after { display: none !important; }
#root .section-title::before { content: "⋮⋮"; position: absolute; left: -22px; top: 50%; transform: translateY(-50%); color: rgba(55, 53, 47, .35); font-size: 14px; letter-spacing: -2px; opacity: 0; transition: opacity .15s; }
#root .section-title:hover::before { opacity: 1; }

/* Posters as a Notion gallery: bordered cards, the title and details under the image, always visible. */
/* Cards keep Movix's exact poster size (2:3): Movix lazy-loads rows into space reserved at that height, so a taller
   card would make the page jump while scrolling. The caption takes its room from the bottom of the image instead. */
#root .media-color-card { display: flex !important; flex-direction: column !important; height: auto !important; aspect-ratio: 2 / 3; border-radius: 4px !important; background: #ffffff !important; box-shadow: rgba(15, 15, 15, .1) 0 0 0 1px, rgba(15, 15, 15, .1) 0 2px 4px !important; transform: none !important; transition: background .15s !important; }
#root .media-color-card:hover { background: #f7f7f5 !important; }
#root .media-color-card > [class~="aspect-[2/3]"] { flex: 1 1 auto; min-height: 0; aspect-ratio: auto !important; }
#root .media-color-card img, #root .media-color-card [class~="aspect-[2/3]"] > div { height: 100% !important; border-radius: 4px 4px 0 0 !important; }
#root .media-card-color-layers, #root .media-color-card > [class~="bg-gradient-to-t"] { display: none !important; }
#root .media-color-card > [class~="bottom-0"][class~="p-3"] { flex: none; position: static !important; padding: 8px 10px 10px !important; opacity: 1 !important; transform: none !important; }
/* Titles stay as text, as in a Notion gallery: Movix swaps them for logo images, which are hidden here. */
#root .media-color-card h3 { position: static !important; opacity: 1 !important; color: #37352f !important; font-size: 14px !important; font-weight: 500 !important; }
#root .media-color-card h3 + div { display: none !important; }
#root .media-color-card [class~="mb-1.5"][class~="h-7"] { height: auto !important; margin-bottom: 2px !important; }
#root .media-color-card [class~="mb-1.5"] ~ div, #root .media-color-card [class~="mb-1.5"] ~ div * { color: #787774 !important; font-size: 12px !important; }
#root .media-color-card p, #root .media-card-muted { display: none !important; }
#root .media-color-card > span[class~="absolute"] { border-radius: 3px !important; background: rgba(255, 255, 255, .92) !important; color: #37352f !important; font-size: 11px !important; font-weight: 500 !important; }
/* The giant outlined Top 10 digits have no place on a calm page. */
#root .ranking-number { display: none !important; }

/* Streaming platform tiles: white cards with a hairline. */
#root .platform-link > div { border-radius: 4px !important; background: #ffffff !important; box-shadow: rgba(15, 15, 15, .1) 0 0 0 1px !important; }
#root .platform-link p { border-radius: 3px !important; background: #f1f1ef !important; color: #37352f !important; font-weight: 500 !important; }

/* Footer: Notion's light gray. */
#root footer { background: #f7f7f5 !important; color: #787774 !important; border-color: rgba(55, 53, 47, .09) !important; }

/* Detail pages read like a Notion database page: page title, properties, tags, callout. */
#root h1.section-title { font-size: 40px !important; font-weight: 700 !important; line-height: 1.2 !important; }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] { grid-template-columns: 1fr !important; gap: 0 !important; max-width: 640px; }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] [class~="md:col-span-2"] { display: contents !important; }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] div:has(> h3) { display: grid !important; grid-template-columns: 180px 1fr; align-items: baseline; min-height: 34px; padding: 4px 6px; border-radius: 4px; }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] div:has(> h3):hover { background: rgba(55, 53, 47, .06); }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] h3 { margin: 0 !important; color: #787774 !important; font-size: 14px !important; font-weight: 400 !important; }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] h3::before { content: "≡"; margin-right: 8px; color: rgba(55, 53, 47, .45); }
#root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] p, #root [class~="grid"][class~="md:grid-cols-2"][class~="gap-4"][class~="mb-6"] span { color: #37352f !important; font-size: 14px !important; }
#root div:has(> h3 + [class~="flex-wrap"]) > [class~="flex-wrap"] a { min-height: 0 !important; padding: 0 6px !important; border: 0 !important; border-radius: 3px !important; background: rgba(227, 226, 224, .75) !important; color: #32302c !important; font-size: 14px !important; line-height: 22px !important; box-shadow: none !important; }
#root div:has(> h3 + [class~="flex-wrap"]) > [class~="flex-wrap"] a > span[class~="rounded-full"] { display: none !important; }
/* Notion pages are plain white: the film's blurred backdrop behind detail pages goes. */
#root .fixed.inset-0.pointer-events-none[style*="background-image"] { display: none !important; }
#root [class~="border-red-500/50"][class~="bg-red-500/10"] { border: 0 !important; border-radius: 4px !important; background: #f7f6f3 !important; }
#root [class~="border-red-500/50"][class~="bg-red-500/10"] > div { color: #37352f !important; }

/* On a wide screen the top bar becomes Notion's sidebar, and the page moves over to make room. */
@media (min-width: 1024px) {
  #root header { right: auto !important; bottom: 0 !important; width: 240px !important; height: 100vh !important; }
  #root header > [class~="absolute"][class~="inset-0"][class~="pointer-events-none"][class~="bg-gradient-to-b"][class~="z-0"] { background: #f7f7f5 !important; border-bottom: 0 !important; border-right: 1px solid rgba(55, 53, 47, .09) !important; }
  #root header > [class~="relative"], #root header [class~="max-w-[1400px]"] { height: 100% !important; max-width: none !important; }
  #root header [class~="h-16"] { height: 100% !important; flex-direction: column !important; align-items: stretch !important; padding: 10px 8px !important; gap: 2px !important; }
  #root header [class~="h-16"] > a[class~="text-2xl"] { order: 0; padding: 4px 8px; border-radius: 4px; }
  #root header [class~="h-16"] > a[class~="h-11"], #root header [class~="h-16"] > [class~="flex-1"] { display: none !important; }
  #root header [class~="h-16"] > [class~="md:block"] { order: 1; width: auto !important; margin: 6px 0 10px; }
  #root header nav { order: 2; display: flex !important; flex-direction: column !important; align-items: stretch !important; gap: 1px !important; }
  #root header nav a, #root header nav button { justify-content: flex-start !important; width: 100%; padding: 4px 10px !important; color: #5f5e5b !important; }
  #root header [class~="h-16"] > div:last-child { order: 3; margin-top: auto; padding: 4px; }
  #root #movix-fullscreen-host { padding-left: 240px !important; }
  /* No top bar any more, so the cover starts at the very top. */
  #root .content-wrapper > [class~="pt-16"] { padding-top: 0 !important; }
}

/* Notion corners are barely rounded: pills (buttons, tags, the slider control) get 4px. Avatars and dots stay round. */
#root :is(button, a, span, div)[class~="rounded-full"]:not(:has(img)) { border-radius: 4px !important; }
/* Notion text never shimmers: decorative text animations stop (loading spinners and pulses keep running). */
/* Movix's shine effect (the search page title, hovered card titles) paints its gradient via an inline style set by
   JS each animation frame, not a class, so the adapter has no selector to hook into. Catch the signature instead:
   this is what made "Rechercher de…" fade into invisible pink/white text on Notion's white page. */
#root [style*="-webkit-text-fill-color"] { background: none !important; -webkit-text-fill-color: currentColor !important; color: #37352f !important; }
#root .footer-vibe-text { animation: none !important; background: none !important; -webkit-text-fill-color: currentColor !important; color: #787774 !important; }
#root :is(h1, h2, h3, h4, p, span, a)[class*="animate-"]:not([class~="animate-spin"]):not([class~="animate-pulse"]) { animation: none !important; }
